def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Lines are split on '=' at the first occurrence, and both the key and the
    value are stripped of surrounding whitespace. Returns an empty string
    when the key is absent. The function operates only on the `text`
    argument and never reads files.
    """
    for line in text.splitlines():
        name, sep, value = line.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_config_value_present_key() -> None:
    assert config_value("host=example.com\nport=8080", "port") == "8080"


def test_config_value_absent_key_returns_empty_string() -> None:
    assert config_value("host=example.com", "port") == ""


def test_config_value_empty_text_returns_empty_string() -> None:
    assert config_value("", "host") == ""


def test_config_value_strips_whitespace_around_key_and_value() -> None:
    assert config_value("  host  =  example.com  ", "host") == "example.com"


def test_config_value_splits_on_first_equals_only() -> None:
    assert config_value("expr=a=b", "expr") == "a=b"


def test_config_value_key_match_is_exact() -> None:
    assert config_value("hostname=x", "host") == ""
